const CALENDAR_COUNTRY_FLAGS = { US: '🇺🇸', GB: '🇬🇧', EU: '🇪🇺', KR: '🇰🇷', CN: '🇨🇳', JP: '🇯🇵' };
// Display code shown in brackets next to the flag — GB shows as "UK" (matches how the
// rest of the site/user refers to it) even though the internal `country` field is 'GB'.
// Korean mode shows the country name in Korean instead of the English code.
const CALENDAR_COUNTRY_CODE_EN = { US: 'US', GB: 'UK', EU: 'EU', KR: 'KR', CN: 'CN', JP: 'JP' };
const CALENDAR_COUNTRY_CODE_KO = { US: '미국', GB: '영국', EU: '유럽', KR: '한국', CN: '중국', JP: '일본' };
function calFlagPrefix(country) {
    const codeMap = currentLang === 'ko' ? CALENDAR_COUNTRY_CODE_KO : CALENDAR_COUNTRY_CODE_EN;
    return `${CALENDAR_COUNTRY_FLAGS[country] || ''} [${codeMap[country] || country}]`;
}
